.store-hero.is-fabric{background:#1b2547;min-height:420px}.store-hero.is-fabric:before,.store-hero.is-fabric:after{display:none}.store-hero.is-fabric .shell{display:grid;grid-template-columns:1.1fr .9fr;gap:42px;align-items:center;padding-block:44px 72px}.is-fabric .store-hero-content{max-width:610px;padding:0}.is-fabric h1{font-size:clamp(2.5rem,5vw,4.6rem);letter-spacing:-.035em;line-height:1.08}.is-fabric p{font-size:1.05rem;color:#d7dceb}.is-fabric .hero-btn{background:#e8a317;color:#141b34;border-radius:14px;min-height:54px;padding-inline:24px}.is-fabric .badge{font-size:.78rem}.fabric-book{height:310px;position:relative;width:100%;max-width:400px;margin:auto}.fabric-swatch{position:absolute;inset-inline-start:calc(50% - 42px);bottom:44px;width:84px;height:235px;transform-origin:50% 100%;transform:rotate(calc(var(--swatch) * 17deg));border-radius:8px;box-shadow:0 8px 20px #0005;border:1px solid #ffffff30;transition:transform .2s}.fabric-swatch:hover,.fabric-swatch:focus-visible{transform:rotate(calc(var(--swatch) * 17deg)) translateY(-14px)}.fabric-swatch img{width:100%;height:100%;object-fit:cover;border-radius:inherit}.fabric-book:after{content:'';position:absolute;width:23px;height:23px;border:5px solid #e8a317;border-radius:50%;background:#8b6419;bottom:48px;inset-inline-start:calc(50% - 12px);pointer-events:none}.fabric-book-label{position:absolute;bottom:0;text-align:center;width:100%;font-size:.82rem;color:#d7dceb}
.fabric-texture{background-color:#a9cbea;background-image:repeating-linear-gradient(90deg,#ffffff66 0 2px,transparent 2px 9px)}.fabric-texture:nth-child(5n+2){background-color:#e8a317;background-image:radial-gradient(#7a3b12 2px,transparent 3px);background-size:18px 18px}.fabric-texture:nth-child(5n+3){background-color:#376b52;background-image:repeating-linear-gradient(45deg,#ffffff22 0 2px,transparent 2px 6px)}.fabric-texture:nth-child(5n+4){background-color:#d9d0bf;background-image:repeating-linear-gradient(0deg,#ffffff55 0 1px,transparent 1px 4px)}.fabric-texture:nth-child(5n+5){background-color:#4b5ca3;background-image:linear-gradient(110deg,#1b2547,transparent,#1b2547)}
.benefits{margin-top:-26px;border-radius:16px;box-shadow:0 8px 25px #141b3410}.benefit{padding:20px;font-size:.88rem;border:0}.benefit+.benefit{border-inline-start:1px solid var(--line)}.fabric-discovery{padding-bottom:0}.fabric-types{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:14px}.fabric-type{background:#fff;border:1px solid var(--line);border-radius:16px;overflow:hidden;text-decoration:none;color:var(--ink);transition:transform .2s}.fabric-type:hover{transform:translateY(-3px)}.fabric-type-art{height:96px;display:grid;place-items:center;color:#1b2547;background:#e5e9f0}.fabric-type-art img{width:100%;height:96px;object-fit:cover}.fabric-type strong{display:block;padding:13px;font-size:.95rem}.fabric-brands{display:flex;align-items:center;flex-wrap:wrap;gap:10px;margin-top:24px}.fabric-brands h3{font-size:.95rem;margin:0;margin-inline-end:8px}.fabric-brands a{padding:8px 17px;border:1px solid var(--line);border-radius:999px;background:#fff;color:var(--ink);text-decoration:none}.fabric-brands a:hover{border-color:var(--primary);color:var(--primary)}.section-heading h2{font-size:1.8rem;letter-spacing:-.025em}.section-link{font-size:.88rem}.commerce-layout{display:block}.product-grid{grid-template-columns:repeat(4,minmax(0,1fr))}.product-photo{aspect-ratio:4/3;background:#e5e9f0}.product-content{padding:18px}.product-content h3{font-size:1.08rem;white-space:normal}.product-meta,.product-stock{font-size:.82rem}.product-price{font-size:1rem}.product-bottom{flex-wrap:wrap}.product-view{width:auto;min-height:44px;padding:8px 12px;gap:7px;display:inline-flex;font-size:.82rem}.product-featured{color:#141b34;background:#e8a317;font-size:.75rem;inset-inline-end:10px;right:auto}.product-stock{margin-top:10px}.fabric-catalog-link{display:flex;justify-content:center;margin-top:25px}
@media(max-width:1000px){.fabric-types{grid-template-columns:repeat(3,minmax(0,1fr))}.product-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.store-hero.is-fabric .shell{gap:20px}.fabric-book{max-width:320px}}
@media(max-width:700px){.store-hero.is-fabric .shell{grid-template-columns:1fr;padding-block:32px 54px}.fabric-book{display:none}.store-hero.is-fabric{min-height:0}.is-fabric h1{font-size:2.6rem}.benefits{grid-template-columns:1fr}.benefit{padding:13px 18px}.benefit+.benefit{border-inline-start:0;border-top:1px solid var(--line)}.section-heading{flex-direction:row;align-items:center}.section-heading h2{font-size:1.45rem}.section-heading p{font-size:.9rem}.fabric-types{grid-template-columns:repeat(2,minmax(0,1fr))}.product-content{padding:12px}.product-content h3{font-size:.95rem}.product-bottom{align-items:stretch;flex-direction:column}.product-view{justify-content:center}.product-price{font-size:.9rem}}
@media(max-width:360px){.product-grid{grid-template-columns:1fr}}
.product-grid{align-items:stretch;grid-auto-rows:1fr}.home-product{display:flex;flex-direction:column;min-width:0;height:100%}.home-product .product-photo{position:relative;flex:none;min-height:0;overflow:hidden}.home-product .product-photo img{position:absolute;inset:0;display:block;width:100%;height:100%;object-fit:cover}.home-product .product-content{display:flex;flex-direction:column;flex:1;min-width:0}.home-product .product-bottom{margin-top:auto;padding-top:14px}
@media(prefers-reduced-motion:reduce){.fabric-swatch,.fabric-type{transition:none}}
